package ae.suffix;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Random;
import org.junit.jupiter.api.Test;

class BwtTest {
    @Test
    void bananaTransform() {
        assertEquals("annb\0aa", Bwt.transform("banana"));
    }

    @Test
    void inverseOfBanana() {
        assertEquals("banana", Bwt.inverse("annb\0aa"));
    }

    @Test
    void emptyString() {
        assertEquals("\0", Bwt.transform(""));
        assertEquals("", Bwt.inverse("\0"));
    }

    @Test
    void sentinelInInputRejected() {
        assertThrows(IllegalArgumentException.class, () -> Bwt.transform("a\0b"));
    }

    @Test
    void invalidBwtRejected() {
        assertThrows(IllegalArgumentException.class, () -> Bwt.inverse("ab")); // no sentinel
        assertThrows(IllegalArgumentException.class, () -> Bwt.inverse("\0\0")); // two sentinels
        assertThrows(IllegalArgumentException.class, () -> Bwt.inverse(""));
        // same multiset as the valid "b\0a" / "ab\0" but not the BWT of anything
        for (String bad : new String[] {"\0ab", "\0ba", "a\0b", "ba\0"}) {
            assertThrows(IllegalArgumentException.class, () -> Bwt.inverse(bad), bad);
        }
        assertEquals("ab", Bwt.inverse("b\0a")); // control: valid ones load
        assertEquals("ba", Bwt.inverse("ab\0"));
    }

    @Test
    void randomRoundTrip() {
        Random r = new Random(99);
        for (int i = 0; i < 400; i++) {
            String s = Naive.random(r, r.nextInt(80), 1 + r.nextInt(5));
            String b = Bwt.transform(s);
            assertEquals(s.length() + 1, b.length());
            assertEquals(s, Bwt.inverse(b), s);
        }
    }

    @Test
    void bwtGroupsRepeatsIntoRuns() {
        String s = "abracadabra".repeat(6);
        String b = Bwt.transform(s);
        int runsIn = runs(s), runsOut = runs(b);
        assertTrue(runsOut < runsIn, runsOut + " >= " + runsIn);
    }

    private static int runs(String s) {
        int n = s.isEmpty() ? 0 : 1;
        for (int i = 1; i < s.length(); i++) if (s.charAt(i) != s.charAt(i - 1)) n++;
        return n;
    }
}

package ae.suffix;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.jupiter.api.Test;

class SuffixIndexTest {
    @Test
    void bananaOccurrences() {
        SuffixIndex idx = new SuffixIndex("banana");
        assertEquals(List.of(1, 3), idx.occurrences("ana"));
        assertEquals(List.of(2), idx.occurrences("nan"));
        assertEquals(3, idx.count("a"));
        assertEquals(1, idx.count("banana"));
        assertEquals(0, idx.count("bananas"));
        assertEquals(0, idx.count("x"));
        assertTrue(idx.contains("nana"));
        assertFalse(idx.contains("nab"));
    }

    @Test
    void emptyPatternRejected() {
        assertThrows(IllegalArgumentException.class, () -> new SuffixIndex("abc").count(""));
        assertThrows(NullPointerException.class, () -> new SuffixIndex(null));
    }

    @Test
    void emptyTextHasNoMatches() {
        SuffixIndex idx = new SuffixIndex("");
        assertEquals(0, idx.count("a"));
        assertEquals("", idx.longestRepeatedSubstring());
        assertEquals(0L, idx.distinctSubstrings());
    }

    @Test
    void longestRepeatedKnownAnswers() {
        assertEquals("ana", new SuffixIndex("banana").longestRepeatedSubstring());
        assertEquals("", new SuffixIndex("abcd").longestRepeatedSubstring());
        assertEquals("aaa", new SuffixIndex("aaaa").longestRepeatedSubstring()); // overlap allowed
        // "ab" (at 0,6) and "cd" (at 3,9) both repeat with length 2; the smaller one wins
        assertEquals("ab", new SuffixIndex("abxcdyabzcd").longestRepeatedSubstring());
    }

    @Test
    void distinctAndKth() {
        SuffixIndex idx = new SuffixIndex("banana");
        assertEquals(15L, idx.distinctSubstrings());
        assertEquals(4L, new SuffixIndex("aaaa").distinctSubstrings());
        assertEquals("a", idx.kthSubstring(1));
        assertEquals("anan", idx.kthSubstring(4));
        assertEquals("b", idx.kthSubstring(6));
        assertEquals("nana", idx.kthSubstring(15));
        assertThrows(IllegalArgumentException.class, () -> idx.kthSubstring(0));
        assertThrows(IllegalArgumentException.class, () -> idx.kthSubstring(16));
    }

    @Test
    void longestCommonSubstringKnownAnswers() {
        assertEquals("abcd", SuffixIndex.longestCommonSubstring("xabcdy", "zabcdw"));
        assertEquals("", SuffixIndex.longestCommonSubstring("abc", "xyz"));
        assertEquals("", SuffixIndex.longestCommonSubstring("", "xyz"));
        assertEquals("ab", SuffixIndex.longestCommonSubstring("abxcd", "cdab")); // tie ab/cd
        assertEquals("a", SuffixIndex.longestCommonSubstring("xa", "ay")); // must not span a|b seam
        assertEquals("ab", SuffixIndex.longestCommonSubstring("ab", "ab"));
    }

    @Test
    void randomDifferentialAgainstNaive() {
        Random r = new Random(2026);
        for (int iter = 0; iter < 300; iter++) {
            String s = Naive.random(r, r.nextInt(41), 1 + r.nextInt(3));
            SuffixIndex idx = new SuffixIndex(s);
            for (int q = 0; q < 8; q++) {
                String p = Naive.random(r, 1 + r.nextInt(4), 1 + r.nextInt(3));
                assertEquals(Naive.occurrences(s, p), idx.occurrences(p), s + " / " + p);
                assertEquals(Naive.occurrences(s, p).size(), idx.count(p));
            }
            assertEquals(Naive.longestRepeated(s), idx.longestRepeatedSubstring(), s);
            List<String> all = new ArrayList<>(Naive.distinct(s));
            assertEquals(all.size(), idx.distinctSubstrings(), s);
            for (int k = 1; k <= all.size(); k++) assertEquals(all.get(k - 1), idx.kthSubstring(k), s);
            String other = Naive.random(r, r.nextInt(30), 1 + r.nextInt(3));
            assertEquals(
                    Naive.longestCommon(s, other),
                    SuffixIndex.longestCommonSubstring(s, other),
                    s + " | " + other);
        }
    }
}

package ae.suffix;

import static org.junit.jupiter.api.Assertions.*;

import java.time.Duration;
import java.util.Random;
import org.junit.jupiter.api.Test;

class SuffixArrayTest {
    @Test
    void bananaSuffixArray() {
        assertArrayEquals(new int[] {5, 3, 1, 0, 4, 2}, SuffixArray.build(Naive.ints("banana")));
    }

    @Test
    void bananaLcp() {
        int[] t = Naive.ints("banana");
        assertArrayEquals(new int[] {0, 1, 3, 0, 0, 2}, SuffixArray.lcp(t, SuffixArray.build(t)));
    }

    @Test
    void emptyAndSingle() {
        assertEquals(0, SuffixArray.build(new int[0]).length);
        assertEquals(0, SuffixArray.lcp(new int[0], new int[0]).length);
        assertArrayEquals(new int[] {0}, SuffixArray.build(new int[] {7}));
        assertArrayEquals(new int[] {0}, SuffixArray.lcp(new int[] {7}, new int[] {0}));
    }

    @Test
    void allEqualCharactersSortShortestFirst() {
        int[] t = Naive.ints("aaaa");
        assertArrayEquals(new int[] {3, 2, 1, 0}, SuffixArray.build(t));
        assertArrayEquals(new int[] {0, 1, 2, 3}, SuffixArray.lcp(t, SuffixArray.build(t)));
    }

    @Test
    void negativeValuesAreOrderedAsInts() {
        int[] t = {3, -1, 3, -5, 0};
        assertArrayEquals(Naive.suffixArray(t), SuffixArray.build(t));
        assertEquals(3, SuffixArray.build(t)[0]); // suffix starting with -5 is smallest
    }

    @Test
    void inputIsNotModified() {
        int[] t = {2, 1, 2, 1};
        int[] copy = t.clone();
        SuffixArray.build(t);
        assertArrayEquals(copy, t);
    }

    @Test
    void randomDifferentialAgainstSortedSuffixes() {
        Random r = new Random(42);
        for (int iter = 0; iter < 600; iter++) {
            String s = Naive.random(r, r.nextInt(61), 1 + r.nextInt(4));
            int[] t = Naive.ints(s);
            int[] sa = SuffixArray.build(t);
            assertArrayEquals(Naive.suffixArray(t), sa, s);
            int[] lcp = SuffixArray.lcp(t, sa);
            for (int i = 1; i < sa.length; i++) {
                int h = 0;
                while (sa[i] + h < t.length && sa[i - 1] + h < t.length
                        && t[sa[i] + h] == t[sa[i - 1] + h]) h++;
                assertEquals(h, lcp[i], s + " at " + i);
            }
        }
    }

    @Test
    void largeInputsBuildQuickly() {
        Random r = new Random(7);
        int n = 300_000;
        int[] rnd = new int[n];
        int[] periodic = new int[n];
        for (int i = 0; i < n; i++) {
            rnd[i] = r.nextInt(4);
            periodic[i] = i % 3; // worst case for doubling: many rounds
        }
        assertTimeoutPreemptively(Duration.ofSeconds(10), () -> {
            for (int[] t : new int[][] {rnd, periodic, new int[n]}) {
                int[] sa = SuffixArray.build(t);
                boolean[] seen = new boolean[n];
                for (int p : sa) seen[p] = true;
                for (boolean b : seen) assertTrue(b);
                for (int i = 1; i < n; i += 997) assertTrue(suffixLess(t, sa[i - 1], sa[i]));
                long sum = 0; // linear-time Kasai: a reset-to-zero variant would take ~n^2 on periodic input
                for (int h : SuffixArray.lcp(t, sa)) sum += h;
                assertTrue(sum >= 0);
            }
        });
    }

    private static boolean suffixLess(int[] t, int a, int b) {
        while (a < t.length && b < t.length) {
            if (t[a] != t[b]) return t[a] < t[b];
            a++;
            b++;
        }
        return a >= t.length && b < t.length;
    }
}
